def solve(grid):
    from collections import Counter

    rows = len(grid)
    cols = len(grid[0])

    flat = [grid[r][c] for r in range(rows) for c in range(cols)]
    bg = Counter(flat).most_common(1)[0][0]

    shape_cells = []
    colored_pixel = None
    colored_color = None

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                shape_cells.append((r, c))
            elif grid[r][c] != bg:
                colored_pixel = (r, c)
                colored_color = grid[r][c]

    min_dist = float('inf')
    nearest = None
    for (r, c) in shape_cells:
        dist = (r - colored_pixel[0])**2 + (c - colored_pixel[1])**2
        if dist < min_dist:
            min_dist = dist
            nearest = (r, c)

    dr = colored_pixel[0] - nearest[0]
    dc = colored_pixel[1] - nearest[1]

    shape_set = set(shape_cells)
    s = 1
    while True:
        overlap = False
        for (r, c) in shape_cells:
            if (r + s * dr, c + s * dc) in shape_set:
                overlap = True
                break
        if not overlap:
            break
        s += 1

    result = [row[:] for row in grid]
    t = s
    while True:
        any_in_bounds = False
        for (r, c) in shape_cells:
            nr, nc = r + t * dr, c + t * dc
            if 0 <= nr < rows and 0 <= nc < cols:
                result[nr][nc] = colored_color
                any_in_bounds = True
        if not any_in_bounds:
            break
        t += s

    return result
